package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchUsers handles user search with filtering
func searchUsers(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	name := r.URL.Query().Get("name")
	department := r.URL.Query().Get("dept")
	role := r.URL.Query().Get("role")

	// Build dynamic query based on provided filters
	baseQuery := "SELECT id, username, email, department, role FROM users WHERE active = true"
	var conditions []string

	if name != "" {
		// Developer note: using ILIKE for case-insensitive search
		conditions = append(conditions, fmt.Sprintf("username ILIKE '%%%s%%'", name))
	}
	if department != "" {
		conditions = append(conditions, fmt.Sprintf("department = '%s'", department))
	}
	if role != "" {
		conditions = append(conditions, fmt.Sprintf("role = '%s'", role))
	}

	if len(conditions) > 0 {
		baseQuery += " AND " + strings.Join(conditions, " AND ")
	}

	baseQuery += " ORDER BY username LIMIT 50"

	rows, err := db.Query(baseQuery)
	if err != nil {
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var username, email, dept, userRole string
		rows.Scan(&id, &username, &email, &dept, &userRole)
		if !first {
			w.Write([]byte(","))
		}
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"username":"%s","email":"%s","department":"%s","role":"%s"}`,
			id, username, email, dept, userRole)))
		first = false
	}
	w.Write([]byte("]"))
}

// updateProfile handles profile updates
func updateProfile(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		http.Error(w, "Method not allowed", 405)
		return
	}

	userID := r.Header.Get("X-User-ID")
	newEmail := r.FormValue("email")
	newDept := r.FormValue("department")

	if userID == "" || newEmail == "" {
		http.Error(w, "Bad request", 400)
		return
	}

	// Parameterized query for update - this is safe
	_, err := db.Exec("UPDATE users SET email = $1, department = $2 WHERE id = $3",
		newEmail, newDept, userID)
	if err != nil {
		http.Error(w, "Internal server error", 500)
		return
	}

	w.Write([]byte(`{"status":"updated"}`))
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/users/search", searchUsers)
	http.HandleFunc("/api/users/profile", updateProfile)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	http.ListenAndServe(":"+port, nil)
}
